formulesCache = new WeakMap();

function __calc__ (Exp) {
	function findMxByPriority (a) {
		let bestIndex = 0;
		for (let i = 0; i < a.length; i++)
			if ((a[bestIndex].priority == undefined) || (a[i].priority > a[bestIndex].priority))
				bestIndex = i;
		return bestIndex;
	}
	let index;
	while (Exp.length > 1) {
		index = findMxByPriority(Exp)
		if (!Exp[index].unary)
			Exp.splice(index - 1, 3, Exp[index].use(Exp[index - 1], Exp[index + 1]));
		else
			Exp.slice(index, 2, Exp[index].use(Exp[index + 1]));
	}
	return Exp[0];
}

function calc (Exp) {
	let arr = [];
	for (let i = 0; i < Exp.length; i++)
		arr.push(Exp[i]);

	let brCount = 0;
	for (let i = 0; i < Exp.length; i++)
		if (arr[i].open)
			brCount++;
		else if (!arr[i].open && arr[i] > 0)
			brCount--;
		/*else
			throw error*/
	function rFindBracket (arr, index0) {
		for (let i = index0 - 1; i > 0; i--)
			if (arr[i].open)
				return i;
		return -1;
	}
	let index, index1;
	while (~(index = arr.findIndex(a => (a.open != undefined) && !a.open))) {
		index1 = rFindBracket(arr, index);
		arr.splice(index, index - index1 + 1, __calc__(arr.slice(index + 1, index1)));
	}
	return __calc__(arr);
}

class Formule extends Array {
	constructor (content=[0]) {
		if (content.length != 1) super(...content)
		else {
			super();
			this[0] = content[0];
		}
		this.recalc();
	}
	recalc () { formulesCache.set(this, calc(this)) }
	change (value) {
		for (let i = 0; i < value.length; i++)
			this[i] = value[i];
		this.length = value.length;
		this.recalc();
	}
	calc() { formulesCache.get(this); }
	static get [Symbol.species]() {
		return Array;
	}
}

class Num {
	constructor (value=0) { this.value = value }
	calc () { return Number(this.value) }
	add (a) { return new Num( this.value + a.calc() ) } 
	sub (a) { return new Num( this.value - a.calc() ) }
	mul (a) { return new Num( this.value * a.calc() ) }
	div (a) { return new Num( this.value / a.calc() ) }
	pow (a) { return new Num( Math.pow(this.value, a.calc()) ) }
}

class Bracket { constructor (open) { this.open = open }}

class Root {
	constructor (content=[new Num()]) {
		this.content = new Formule(content);
	}
	calc () {
		let calculatedExp = this.content.calc();
		
	}
}

class Action {
	constructor (use, priority, unary=false) {
		this.priority = priority;
		this.use = (a, b) => {
			try {
				return use(a, b);
			}
			catch (e) {

			}
		}
	}
}

// class Action checks for errors like incompatible types
// his objects like plus minus, etc. just call prototype functions
// like for Num its plus minus, etc.
// if object like Vector doesn't have such function, this error will be captured in Action class

let plus = new Action ((a, b) => a.add(b), 3),
	minus = new Action ((a, b) => a.sub(b), 3),
	multip = new Action ((a, b) => a.mul(b), 4),
	div = new Action ((a, b) => a.div(b), 4),
	pow = new Action ((a, b) => a.pow(b), 5);

let events = [];

events.calling = true;
events.push = function () {
	[].push.call(this, ...arguments);
	if (this.calling) {
		setTimeout(function(){
			EventCycle();
		}, 0);
	}
}

let errors = [];

errors.push = function () {
	[].push.call(this, ...arguments);
	setTimeout(onerror, 0);
}

function EventCycle () {
	events.calling = false;
	eventCycle: while (events.length > 0) {
		for (let i = events.length - 1; i >= 0; i--) { // acts like this because of splicing
			switch (events[i].type) {
				case 'variableChange':
					// remake later for preventing infinite loop {
					// 		2 variants:
					// 			1. algorithm that will calc whole variables in first(many) iterations and
					// 				check if some events happened again in changed variable
					// 			2. just checking formule on containing event.place
					// 			
					// 		first is better cause it may be chain of dependence
					// }
					try {
						events[i].place.formule.recalc();
					}
					catch (e) {
						errors.push({

						});
					}

					for (let variable of variables)
						variable.react(events[i]);
					
					events.splice(i, 1);

					break;
			}
		}
	}
	events.calling = true;
}

class MathError {

}

class MathEvent {
	constructor (type='event', message='', place) {
		this.type = type;
		this.message = message;
		this.place = place;
	}
	dispatch () {
		events.push(this);
	}
}

let variables = new Set();

class Variable {
	constructor (formule = new Formule()) {
		this.formule = formule;
		this.event = new MathEvent('variableChange', 'This variable changed', this);
		variables.add(this);
	}

	delete () {
		variables.delete(this);
	}

	change (value) {
		this.formule.change(value);
		this.event.dispatch();
	}

	calc () {
		return formulesCache.get(this.formule).calc();
	}

	react (event) {
		let p = event.place;
		if (this.formule.some(a => a == p)) {
			this.event.dispatch();
		}
	}

	add (b) { return new Num( this.calc() + b.calc() ) }
	minus (b) { return new Num( this.calc() - b.calc() ) }
	mul (b) { return new Num( this.calc() * b.calc() ) }
	div (b) { return new Num( this.calc() / b.calc() ) }
	pow (b) { return new Num( Math.pow(this.calc(), b.calc()) ) }
}

